-- Exercises for the sample course (content/sample-course.md).
insert into public.exercises (lesson_id, position, type, content, solution, explanation) values
  ('what-is-an-ai-agent', 1, 'multiple_choice',
   '{"question": "What makes an AI agent different from a regular chatbot?", "options": ["It can plan steps and use tools to finish a task on its own", "It always gives longer answers", "It doesn''t use a language model", "It only works offline"]}',
   '{"correct": 0}',
   'A chatbot answers your message. An agent works toward a goal: it plans the steps, takes actions with tools (web search, email, spreadsheets) and checks the results.'),
  ('what-is-an-ai-agent', 2, 'multiple_choice',
   '{"question": "Which task is the best fit for an AI agent?", "options": ["\"Find our 5 biggest competitors, check their pricing pages and put the results in a table\"", "\"Write one sentence for a birthday card\"", "\"What is 2 + 2?\""]}',
   '{"correct": 0}',
   'Agents shine at tasks with several steps that need tools and end with a clear result. A single short answer doesn''t need an agent.'),
  ('what-is-an-ai-agent', 3, 'multiple_choice',
   '{"question": "An agent works in a loop. What is the right order?", "options": ["Plan → act → check the result → repeat", "Act → stop", "Check → plan → stop", "Guess → finish"]}',
   '{"correct": 0}',
   'The agent makes a plan, takes an action, looks at what happened and decides the next step, until the goal is reached.'),
  ('what-is-an-ai-agent', 4, 'multiple_choice',
   '{"question": "True or false: AI agents never make mistakes, so you don''t need to check their work.", "options": ["True", "False"]}',
   '{"correct": 1}',
   'Agents can misread data or make up facts that sound right. Always review important work before you use it.'),
  ('agents-in-marketing-work', 1, 'multiple_choice',
   '{"question": "You want an agent to draft a weekly social media report. What should you give it?", "options": ["A clear goal, access to the analytics data and an example of a good report", "Just the words \"make a report\"", "The passwords to all company accounts", "Nothing, it will figure it out"]}',
   '{"correct": 0}',
   'A clear goal, the right data and a good example lead to better results. Give the agent only the access it needs for the task.'),
  ('agents-in-marketing-work', 2, 'multiple_choice',
   '{"question": "An agent wrote 10 ad variations. What is the best next step?", "options": ["Review them, pick the best ones and check the claims and brand tone before publishing", "Publish all 10 right away", "Ask the agent if they are good and publish whatever it says", "Delete them and write your own"]}',
   '{"correct": 0}',
   'Agents are great at producing drafts fast. A person stays in the loop to check facts, tone and quality before anything goes public.'),
  ('agents-in-marketing-work', 3, 'multiple_choice',
   '{"question": "Which marketing task should an agent NOT do on its own?", "options": ["Approve the final budget for a new campaign", "Collect competitor posts from last week", "Group customer reviews into themes", "Draft email subject lines"]}',
   '{"correct": 0}',
   'Decisions about money and risk stay with people. The agent can prepare the information, but a person decides.'),
  ('agents-in-marketing-work', 4, 'multiple_choice',
   '{"question": "An agent''s report says: \"Our Instagram followers grew by 300% last month.\" It sounds too good. What do you do?", "options": ["Check the number in the analytics tool yourself", "Share it with the team right away", "Ask the agent for a nicer chart", "Ignore it"]}',
   '{"correct": 0}',
   'Surprising numbers are a signal to double-check. The agent may have misread the data or made a mistake.');
